import json, glob, collections, math, statistics
def rows_of(g):
    out=[]
    for p in glob.glob(f"runs/feed/g{g}_*.json"): out += json.load(open(p))
    return out

# which team are we? match g35 issued charges to our submitted board
board = {r["index"]: r["charge_price"] for r in json.load(open("runs/game_35.json"))["submissions"][-1]["rows"]}
cand = collections.Counter()
for r in rows_of(35):
    a = board.get(r["line_item_index"])
    if a and r["amount"] and abs(r["amount"] - min(a, r["amount"]))<0.01:
        pass
# simpler: issuer whose accepted amounts match our a values
per_team = collections.defaultdict(set)
for r in rows_of(35):
    if r["accepted"] and r["amount"]:
        per_team[r["issuer"]].add((r["line_item_index"], round(r["amount"],1)))
ours = {(i, round(a,1)) for i,a in board.items()}
best = max(per_team, key=lambda t: len(per_team[t] & ours))
print("we are:", best, " overlap:", len(per_team[best]&ours), "of", len(per_team[best]))

# per-team aggression: charge vs proven bracket, g34-36
truth = {}
for g in (34,35,36):
    try: truth[g] = json.load(open(f"runs/truth_game_{g:02d}.json"))
    except OSError: pass
ratio = collections.defaultdict(list)
fraud_inc = collections.Counter(); fair_inc = collections.Counter()
for g,tv in truth.items():
    # issued amount per issuer/item: use max amount seen in rows (payout = a for fair-refused / accepted)
    seen = collections.defaultdict(float)
    for r in rows_of(g):
        if r["amount"]:
            k=(r["issuer"], r["line_item_index"])
            seen[k]=max(seen[k], r["amount"])
    for (team,i),a in seen.items():
        b = tv.get(str(i))
        if not b: continue
        lo,hi = float(b["t_lo"] or 0), b.get("t_hi")
        tstar = math.sqrt(lo*float(hi)) if lo>0 and hi else (lo if lo>0 else (float(hi) if hi else 0))
        if tstar>0: ratio[team].append(a/tstar)
    for r in rows_of(g):
        if not r["amount"]: continue
        b = tv.get(str(r["line_item_index"]))
        if not b: continue
        hi = b.get("t_hi")
