def feed(g):
    rows, seen = [], set()
    for t in TS:
        for r in transactions(g, t):
            k = (r["issuer"], r["reviewer"], r["line_item_index"])
            if k not in seen: seen.add(k); rows.append(r)
    return rows

def score(g, rows_ab, truth, feedrows):
    """income from truth brackets, expense from the actual charges billed to us under b."""
    inc = 0.0; n_over = n_under = 0; whale_over = 0
    for i, (a, b) in rows_ab.items():
        tv = truth.get(str(i)) or {}; lo, hi = float(tv.get("t_lo") or 0), tv.get("t_hi")
        if a <= 0: continue
        if lo > 0 and a <= lo: inc += 16*a
        elif hi and a >= float(hi):
            ts = math.sqrt(lo*float(hi)) if lo > 0 else float(hi)*0.8
            inc += 16*0.5*ts; n_over += 1
            if ts >= 2000: whale_over += 1
        else: inc += 16*a  # grey: not proven fraud; treat as paid
        if lo > 0 and a < 0.85*lo: n_under += 1
    exp = 0.0
    for r in feedrows:
        if r["reviewer"] != US or not r["amount"]: continue
        i = r["line_item_index"]; c = r["amount"]
        b = rows_ab.get(i, (0, 0))[1]
        tv = truth.get(str(i)) or {}; lo, hi = float(tv.get("t_lo") or 0), tv.get("t_hi")
        fair = c <= lo; fraud = bool(hi) and c >= float(hi)
